
const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'Cerrar':'Menú';nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='Menú'}));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='Menú';menu.focus()}});document.querySelectorAll('details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)document.querySelectorAll('details').forEach(other=>{if(other!==d)other.open=false})}));

const intelligenceStages=[{"name": "Brief y contexto", "input": "El brief, las restricciones y las fuentes disponibles.", "work": "Investigamos mercado, competencia, consumidor y entorno con apoyo de IA y revisión experta.", "output": "Un contexto estratégico que orienta las preguntas del proyecto.", "review": "Si cambia una premisa del negocio, revisamos los objetivos y el alcance."}, {"name": "Objetivos de investigación", "input": "El contexto comprendido y la decisión que necesita apoyar el cliente.", "work": "Traducimos el reto en objetivos, preguntas clave y un plan de investigación.", "output": "Objetivos acordados que dan propósito a cada análisis.", "review": "Contrastamos nuevas preguntas con la necesidad original para mantener el enfoque."}, {"name": "Arquitectura analítica", "input": "Los objetivos y las respuestas que necesitamos obtener.", "work": "Diseñamos módulos, modelos y variables antes de construir el instrumento.", "output": "Una ruta: pregunta de negocio → respuesta esperada → análisis → información necesaria.", "review": "Si falta una variable o un análisis no responde al objetivo, ajustamos el diseño."}, {"name": "Muestra y cuestionario", "input": "La arquitectura analítica y la población que queremos comprender.", "work": "Diseñamos o apoyamos muestra, cuestionario y validación del instrumento. Acordamos quién realiza el levantamiento.", "output": "Un instrumento alineado con los análisis y un plan de obtención de información.", "review": "El pretest y la viabilidad del campo pueden requerir revisar preguntas y cobertura."}, {"name": "Validación y calidad de datos", "input": "La base obtenida y el cuestionario, o las fuentes acordadas para el proyecto.", "work": "Relacionamos variables y estructura; aplicamos controles y revisamos anomalías y faltantes.", "output": "Una base revisada y límites documentados para la ejecución.", "review": "Una inconsistencia puede exigir corregir datos o acotar un análisis, no ocultar el problema."}, {"name": "Ejecución analítica", "input": "La base revisada, la arquitectura y los criterios del proyecto.", "work": "Desarrollamos scripts y ejecutamos modelos y análisis; contrastamos consistencia y resultados.", "output": "Resultados reproducibles vinculados con las preguntas de negocio.", "review": "Los diagnósticos pueden requerir ajustar el modelo y revisar los supuestos."}, {"name": "Descubrimiento de insights", "input": "Los resultados del plan, el contexto y los hallazgos adicionales.", "work": "Integramos y contrastamos evidencia, exploramos patrones y priorizamos implicaciones.", "output": "Insights que explican qué significa el resultado y por qué importa.", "review": "Un hallazgo adicional se valida antes de incorporarlo a la historia o abrir otra pregunta."}, {"name": "Entrega ejecutiva", "input": "Los insights priorizados y la decisión original.", "work": "Construimos la narrativa, los soportes y las recomendaciones; desarrollamos herramientas según el alcance.", "output": "Una presentación, reporte o herramienta con contexto, evidencia y límites.", "review": "Las preguntas del equipo retroalimentan la interpretación; el seguimiento se acuerda con el cliente."}];
const applications=[{"title": "Oferta y precios en moda", "question": "Evaluar ofertas, precios y promociones en moda.", "status": "INVESTIGACIÓN APLICADA + HERRAMIENTA DE CONSULTA", "intro": "Trabajamos una investigación para comprender la elección de prendas y evaluar alternativas de producto, precio y promoción. Conectamos el diseño del estudio, la interpretación de resultados y una herramienta interactiva para explorar escenarios.", "anchor": "¿Cómo se relacionan producto, precio y promoción con la preferencia?", "limit": "Alcance: evaluación de preferencias y escenarios bajo las condiciones del estudio. No equivale a pronosticar ventas. La muestra pública omite marcas, cifras y resultados del cliente.", "steps": ["Partimos del brief y revisamos el contexto de la categoría para precisar qué necesitaba evaluar el negocio.", "Tradujimos la necesidad en preguntas sobre elección de prendas, precios y promociones, con objetivos y alcance acordados.", "Organizamos los módulos de análisis y la información necesaria para responder cada pregunta, antes de definir el instrumento.", "El diseño de la investigación se conectó con el cuestionario y los ejercicios de evaluación. En este proyecto, el cliente realizó el levantamiento.", "Revisamos la correspondencia entre la información recibida, el cuestionario y el diseño del estudio antes del análisis.", "Desarrollamos los análisis acordados para estudiar preferencias y comparar alternativas de oferta, manteniendo sus condiciones y límites.", "Integramos las distintas lecturas para explicar las implicaciones comerciales y las alternativas que convenía evaluar.", "Entregamos una presentación y un simulador/reporteador con filtros y guía, para consultar resultados y explorar escenarios."], "built": "Una solución de investigación y análisis acompañada de un simulador/reporteador, con consulta por perfiles y materiales para interpretar los resultados.", "method": "El brief y el contexto orientaron las preguntas de negocio. La arquitectura analítica guio la propuesta, el instrumento y los análisis; los hallazgos se integraron en una lectura comercial y una herramienta de uso.", "delivered": "Presentación ejecutiva, resultados de soporte, simulador/reporteador con filtros y guía de uso para comparar escenarios dentro del alcance del estudio."}, {"title": "Text Analytics y desarrollo", "question": "De respuestas abiertas a información que puede analizarse.", "status": "ANÁLISIS DE TEXTO + SOFTWARE PROPIO", "intro": "Estructuramos comentarios y respuestas abiertas para identificar temas, asociaciones y diferencias entre perfiles. También desarrollamos un motor propio de clasificación para apoyar este trabajo con IA y revisión humana.", "anchor": "¿Qué expresan las personas, cómo se relacionan los temas y qué implica para el negocio?", "limit": "Alcance: clasificación y análisis interpretativo con revisión humana. La frecuencia de un tema no demuestra su importancia comercial; el motor no se atribuye a todos los estudios.", "steps": ["El brief y el contexto permiten entender para qué necesitamos escuchar a las personas y qué fuentes son pertinentes.", "Se definen las preguntas que guiarán la lectura de opiniones y su relación con otras medidas del estudio.", "Se acuerda cómo analizar e integrar textos, atributos y resultados cuantitativos, y qué información requiere cada módulo.", "Se apoyan preguntas abiertas e instrumentos que permitan responder a los objetivos, según el diseño y las fuentes del proyecto.", "Se revisan estructura, cobertura y textos disponibles antes de su integración analítica.", "Procesamos los textos, clasificamos respuestas y analizamos patrones y asociaciones. El motor propio puede asistir la clasificación con IA; la revisión humana resuelve ambigüedades y verifica su utilidad.", "Se contrastan temas, diferencias y evidencia cuantitativa para elaborar una interpretación contextualizada.", "Entregamos resultados trazables en bases codificadas, tablas, visualizaciones y presentación. Las herramientas de consulta se incluyen según el alcance."], "built": "Un motor de procesamiento y clasificación de texto, con revisión de casos ambiguos, controles y salidas para análisis. Es una capacidad propia que se incorpora según el proyecto.", "method": "Preparación de textos, definición de categorías, clasificación temática o semántica y revisión experta. En estudios aplicados, integramos evidencia cualitativa y cuantitativa para interpretar las diferencias.", "delivered": "Bases codificadas, tablas y visualizaciones de temas, asociaciones y perfiles; una presentación que conecta esos resultados con la pregunta de negocio."}, {"title": "Auditoría visual de publicidad", "question": "Software propio para auditar evidencia visual en publicidad.", "status": "DESARROLLO PROPIO · APLICACIÓN EN MOVILIDAD", "intro": "Desarrollamos una solución que analiza videos y ayuda a identificar señales observables de orientación hacia una pantalla publicitaria. Combina análisis automatizado y auditoría humana para organizar la evidencia y facilitar su revisión.", "anchor": "¿Qué evidencia visual puede revisarse para estudiar la orientación hacia la publicidad?", "limit": "Alcance: conducta visual observable. No mide atención cognitiva ni equivale a eye tracking. Los resultados dependen de las condiciones de captura y validación; no se declara una precisión nueva en esta muestra.", "steps": ["Precisamos el contexto de exposición y la pregunta que la revisión de videos debía ayudar a responder.", "Definimos qué conducta observable estudiar y qué indicadores serían útiles para el proyecto.", "Conectamos los criterios de observación, la información requerida y las salidas necesarias para una auditoría revisable.", "Adaptamos el diseño a las condiciones de video y a la evidencia disponible, sin imponer un instrumento de encuesta.", "Revisamos si el material permite evaluar la conducta visual y distinguimos los casos sin evidencia suficiente.", "El software combina análisis automatizado y revisión humana para preclasificar evidencia y generar métricas.", "Interpretamos los indicadores junto con su cobertura y condiciones de observación, sin equipararlos a atención cognitiva.", "Entregamos reportes con indicadores y evidencia fotográfica para revisar la clasificación y discutir sus alcances."], "outputs": ["Una pregunta situada en su contexto de exposición.", "Un objetivo observable y un alcance explícito.", "Criterios de análisis conectados con los entregables.", "Condiciones de observación adaptadas al material.", "Evidencia evaluable y límites de cobertura identificados.", "Métricas y preclasificaciones sujetas a revisión.", "Una interpretación contextualizada y acotada.", "Reportes revisables con evidencia y límites de uso."], "built": "Software que organiza la revisión de videos, preclasifica evidencia y genera métricas por video, formato y categoría.", "method": "La pregunta del proyecto orienta qué observar, qué métricas generar y cómo interpretar los resultados. El ecosistema conecta contexto, criterios de análisis, desarrollo de la herramienta y revisión experta.", "delivered": "Reportes con indicadores y evidencia fotográfica que permiten revisar los resultados y apoyar su interpretación."}];
let intelligenceStage=0,applicationStage=0,applicationIndex=0;
function renderIntelligence(){
 const item=intelligenceStages[intelligenceStage];
 document.querySelectorAll('[data-intelligence-stage]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.intelligenceStage)===intelligenceStage)));
 document.querySelector('[data-intelligence-number]').textContent='ETAPA '+String(intelligenceStage+1).padStart(2,'0')+' DE 08';
 document.querySelector('[data-intelligence-title]').textContent=item.name;
 document.querySelectorAll('[data-intelligence]').forEach(e=>{e.textContent=item[e.dataset.intelligence]});
}
function renderApplication(){
 const item=applications[applicationIndex];
 document.querySelectorAll('[data-application]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.application)===applicationIndex)));
 document.querySelectorAll('[data-application-field]').forEach(e=>{e.textContent=item[e.dataset.applicationField]});
 document.querySelectorAll('[data-application-stage]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.applicationStage)===applicationStage)));
 document.querySelector('[data-application-number]').textContent='ETAPA '+String(applicationStage+1).padStart(2,'0')+' DE 08';
 document.querySelector('[data-application-title]').textContent=intelligenceStages[applicationStage].name;
 document.querySelector('[data-application-text]').textContent=item.steps[applicationStage];
 document.querySelector('[data-application-return]').textContent=item.outputs ? item.outputs[applicationStage] : intelligenceStages[applicationStage].output;
}
document.querySelectorAll('[data-intelligence-stage]').forEach(b=>b.addEventListener('click',()=>{intelligenceStage=Number(b.dataset.intelligenceStage);renderIntelligence()}));
document.querySelectorAll('[data-application]').forEach(b=>b.addEventListener('click',()=>{applicationIndex=Number(b.dataset.application);renderApplication()}));
document.querySelectorAll('[data-application-stage]').forEach(b=>b.addEventListener('click',()=>{applicationStage=Number(b.dataset.applicationStage);renderApplication()}));
